  it('fails on the patched build', function () {
    // Test that the original behavior is preserved: decimalPlaces defaulting to 2
    // and that the patched version incorrectly uses true as a condition
    const original = bytes.format(1234567, { decimalPlaces: undefined });
    const patched = bytes.format(1234567, { decimalPlaces: undefined });

    // The original should use default decimalPlaces = 2
    // The patched version, due to `(options && true)`, will use options.decimalPlaces
    // which is undefined, so it should fall back to 2 as well — but wait, the logic is broken.
    // Actually, the condition `(options && true)` is always true, so it will always use options.decimalPlaces,
    // even if it's undefined. That means it will pass `undefined` to toFixed(), which is invalid.
    // So the patched version will fail to format correctly.

    // But the original version uses `(options && options.decimalPlaces !== undefined)`
    // so it defaults to 2 when not provided.

    // So the patched version should fail to format when decimalPlaces is not provided,
    // while the original should not.

    // However, we need to check: does `toFixed(undefined)` throw or return '0'? It returns '0'.
    // But let's test the actual behavior.

    // The original behavior: should return '1.18 MB' (1234567 / 1e6 = 1.234567 -> 1.23)
    const expected = '1.23 MB';

    // The patched version: uses options.decimalPlaces = undefined, so toFixed(undefined)
    // which is toFixed(0) — so it becomes '1 MB'
    const actual = bytes.format(1234567, { decimalPlaces: undefined });

    assert.strictEqual(actual, expected);
  });
});

